import{_ as a,o as e,c as s,a5 as d}from"./chunks/framework.DGp912Ge.js";const g=JSON.parse('{"title":"Target Go — C++ 예제","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/software/sdk/cpp/target-go.md","filePath":"ko/software/sdk/cpp/target-go.md","lastUpdated":1783328958000}'),i={name:"ko/software/sdk/cpp/target-go.md"};function o(r,t,c,l,n,h){return e(),s("div",null,[...t[0]||(t[0]=[d(`<h1 id="target-go-—-c-예제" tabindex="-1">Target Go — C++ 예제 <a class="header-anchor" href="#target-go-—-c-예제" aria-label="Permalink to &quot;Target Go — C++ 예제&quot;">​</a></h1><p><strong>소스</strong>: <code>rbq_sdk/cpp/example/src/rbq_target_go.cpp</code></p><p>로봇이 <strong>목표 자세(x, y, 방향)로 걸어가도록</strong> 명령하는 1회성 발행 예제입니다. 선택한 보행(gait)과 접근 모드(mode)로 <code>rt/rbq/cmd/target_go</code>에 <code>TargetGo</code> 메시지를 한 번 발행하고 종료합니다.</p><h2 id="동작-방식" tabindex="-1">동작 방식 <a class="header-anchor" href="#동작-방식" aria-label="Permalink to &quot;동작 방식&quot;">​</a></h2><ol><li>명령행에서 <code>interface</code>와 선택 인자 <code>x y theta gait mode</code>를 읽습니다.</li><li>해당 인터페이스로 DDS <code>ChannelFactory</code>를 초기화하고 <code>rt/rbq/cmd/target_go</code>에 <code>Publisher&lt;TargetGo_&gt;</code>를 생성합니다.</li><li>DDS 디스커버리를 ~500 ms 기다린 뒤 <code>TargetGo</code> 필드를 채워 <strong>한 번</strong> 발행하고, 보낸 값을 출력한 뒤 종료합니다.</li></ol><p>로봇 측 <strong>QuadWalk</strong> 보행 엔진이 <code>rt/rbq/cmd/target_go</code>를 구독해 실제 보행을 수행합니다.</p><h2 id="사전-요구사항" tabindex="-1">사전 요구사항 <a class="header-anchor" href="#사전-요구사항" aria-label="Permalink to &quot;사전 요구사항&quot;">​</a></h2><ul><li>RBQ SDK 빌드 및 설치 완료 — <a href="/RBQ/ko/software/sdk/cpp/overview.html">C++ SDK 개요</a> 참조.</li><li>로봇 스택이 실행 중(시뮬레이터 또는 하드웨어)이며 동일 DDS 인터페이스에서 접근 가능해야 합니다.</li><li><strong>먼저 로봇이 전원 ON / 제어 시작(started) 및 기립 상태여야 합니다.</strong> 제어 시작 전에 목표를 발행하면 QuadWalk가 <code>Can&#39;t Receive cmd: CON_START first</code>로 거부합니다.</li></ul><h2 id="빌드" tabindex="-1">빌드 <a class="header-anchor" href="#빌드" aria-label="Permalink to &quot;빌드&quot;">​</a></h2><p><code>rbq_sdk/cpp/example/</code>에서:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/setup.bash</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/build.bash</span></span></code></pre></div><p>바이너리 위치: <code>bin/rbq_target_go</code></p><h2 id="실행" tabindex="-1">실행 <a class="header-anchor" href="#실행" aria-label="Permalink to &quot;실행&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/rbq_target_go</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">interfac</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [x] [y] [theta_deg] [gait] [mode]</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 시뮬레이터, wave 보행으로 1 m 전진:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/rbq_target_go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1.0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span></span></code></pre></div><p><strong>실행 중인 로봇/심과 같은 인터페이스</strong>(<code>lo</code> 또는 본인 NIC)를 쓰세요. 디스커버리가 안 되면 <a href="/RBQ/ko/software/sdk/cpp/image-echo.html">Image Echo</a> 페이지의 인터페이스 설명을 참고하세요(<code>lo</code>는 멀티캐스트 미지원인 경우가 많아 <code>enp3s0</code> 같은 실제 NIC 권장).</p><p>인자 (예제 자체 usage 기준):</p><table tabindex="0"><thead><tr><th>인자</th><th>의미</th><th>기본값</th></tr></thead><tbody><tr><td><code>interface</code></td><td>CycloneDDS 인터페이스 (<code>lo</code> 심 / NIC 실로봇)</td><td>필수</td></tr><tr><td><code>x</code></td><td>목표 X (m), 시작 기준 상대</td><td>1.0</td></tr><tr><td><code>y</code></td><td>목표 Y (m), 시작 기준 상대</td><td>0.0</td></tr><tr><td><code>theta_deg</code></td><td>목표 방향</td><td>0.0</td></tr><tr><td><code>gait</code></td><td><code>0</code>=wave / <code>1</code>=stairs / <code>2</code>=RL</td><td>0</td></tr><tr><td><code>mode</code></td><td><code>0</code>=회전→직진→회전 / <code>1</code>=회전→대각 / <code>2</code>=대각→회전 / <code>3</code>=회전+대각 동시</td><td>0</td></tr></tbody></table><h2 id="출력-예시" tabindex="-1">출력 예시 <a class="header-anchor" href="#출력-예시" aria-label="Permalink to &quot;출력 예시&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[rbq_target_go] published: gait=0 mode=0 x=1 y=0 theta=0</span></span></code></pre></div><p>한 번 발행 후 종료하며, 이후 로봇이 목표로 걸어갑니다. MuJoCo 시뮬레이터로 검증함 — QuadWalk가 <code>rt/rbq/cmd/target_go</code>에서 명령을 수신합니다. 단 제어 시작 전이면 <code>Can&#39;t Receive cmd: CON_START first</code>가 출력되니, 목표를 보내기 전에 제어를 시작(전원 ON + 기립)하세요.</p>`,20)])])}const k=a(i,[["render",o]]);export{g as __pageData,k as default};
